import os, pty, subprocess, time, select, sys, tempfile

def interact(inputs, env=None, timeout=3):
    master, slave = pty.openpty()
    p = subprocess.Popen(['./executable','--norc'], stdin=slave, stdout=slave, stderr=slave, env=env or os.environ.copy(), close_fds=True)
    os.close(slave)
    out=b''
    start=time.time(); idx=0
    while time.time()-start<timeout:
        r,_,_=select.select([master],[],[],0.05)
        if r:
            try:
                data=os.read(master,4096)
                if not data: break
                out+=data
            except OSError: break
        if idx<len(inputs) and time.time()-start>inputs[idx][0]:
            os.write(master, inputs[idx][1]); idx+=1
        if p.poll() is not None:
            # drain
            time.sleep(0.1)
            while True:
                r,_,_=select.select([master],[],[],0)
                if not r: break
                try: out+=os.read(master,4096)
                except OSError: break
            break
    try: os.close(master)
    except: pass
    try: rc=p.wait(timeout=1)
    except: p.kill(); rc='kill'
    return rc,out
rc,out=interact([(0.3,b'echo hi\r'),(0.6,b'exit\r')])
print('rc',rc)
print(repr(out.decode('utf-8','replace')))
