#!/usr/bin/env python3
import os, sys, subprocess, glob as pyglob, fnmatch, re, time, shutil, tempfile, signal
from dataclasses import dataclass

VERSION = "0.4.2"

HELP_TEMPLATE = """nsh 0.4.2
A command-line shell that focuses on performance and productivity.

USAGE:
    {prog} [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed
"""

class ParseError(Exception):
    def __init__(self, msg="parse error"):
        self.msg = msg

class ShellExit(Exception):
    def __init__(self, code=0):
        self.code = int(code) & 0xff

class BreakSignal(Exception):
    pass
class ContinueSignal(Exception):
    pass
class ReturnSignal(Exception):
    def __init__(self, status=0): self.status=status

@dataclass
class Span:
    typ: str
    val: object
    quoted: bool = False

@dataclass
class Word:
    spans: list
    raw: str = ""
    quoted: bool = False
    def literal_unquoted(self):
        return (not self.quoted and len(self.spans)==1 and self.spans[0].typ=='lit' and not self.spans[0].quoted)
    def lit_text(self):
        if len(self.spans)==1 and self.spans[0].typ=='lit':
            return self.spans[0].val
        if all(s.typ=='lit' for s in self.spans):
            return ''.join(s.val for s in self.spans)
        return None

@dataclass
class Tok:
    typ: str
    val: object = None
    fd: object = None

# AST nodes are small tuples: ('simple', elems), ('pipe',[cmds]), ('andor',[(op,node)]), ('list',[(sep,node)]), etc.

def is_name(s):
    return re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', s or '') is not None

# ---------------------- heredoc preprocessing ----------------------

def scan_heredoc_markers(line):
    markers=[]; i=0; n=len(line); quote=None; esc=False
    while i<n:
        c=line[i]
        if quote:
            if quote=='"':
                if esc: esc=False
                elif c=='\\': esc=True
                elif c=='"': quote=None
            elif quote=="'":
                if c=="'": quote=None
            i+=1; continue
        if c in "'\"": quote=c; i+=1; continue
        if c=='#' and (i==0 or line[i-1].isspace()):
            break
        if line.startswith('<<', i):
            if i+2<n and line[i+2]=='-':
                # unsupported; let the parser complain later
                i+=2; continue
            j=i+2
            while j<n and line[j] in ' \t': j+=1
            mstart=j
            while j<n and (line[j].isalnum() or line[j]=='_'):
                j+=1
            if j>mstart:
                markers.append(line[mstart:j])
            i=j; continue
        i+=1
    return markers

def preprocess_heredocs(script):
    lines = script.splitlines(True)
    out=[]; hdocs=[]; i=0
    while i < len(lines):
        line=lines[i]
        out.append(line)
        markers=scan_heredoc_markers(line)
        i += 1
        for marker in markers:
            content=[]
            found=False
            while i < len(lines):
                raw=lines[i]
                stripped=raw[:-1] if raw.endswith('\n') else raw
                if stripped == marker:
                    found=True; i += 1; break
                content.append(raw[:-1] if raw.endswith('\n') else raw)
                i += 1
            if not found:
                raise ParseError("parse error")
            hdocs.append('\n'.join(content) + '\n')
    return ''.join(out), hdocs

# ---------------------- tokenizer ----------------------

class Tokenizer:
    def __init__(self, text):
        self.text=text; self.i=0; self.n=len(text)
        self.toks=[]
        self.at_boundary=True

    def peek(self, k=0):
        j=self.i+k
        return self.text[j] if j<self.n else ''

    def starts(self, s):
        return self.text.startswith(s, self.i)

    def tokenize(self):
        while self.i < self.n:
            c=self.peek()
            if c in ' \t\r':
                self.i += 1; self.at_boundary=True; continue
            if c=='\n':
                self.toks.append(Tok('OP','\n')); self.i+=1; self.at_boundary=True; continue
            if c=='#' and self.at_boundary:
                while self.i<self.n and self.peek()!='\n': self.i+=1
                continue
            # process substitution can begin a word
            if self.starts('<(') or self.starts('>('):
                self.toks.append(Tok('WORD', self.read_word()))
                self.at_boundary=False; continue
            # redirections with optional fd at word start
            if c.isdigit():
                j=self.i
                while j<self.n and self.text[j].isdigit(): j+=1
                if j<self.n and self.text[j] in '<>':
                    fd=int(self.text[self.i:j]); ch=self.text[j]
                    if ch=='>' and j+1<self.n and self.text[j+1]=='&':
                        self.toks.append(Tok('REDIR','>&',fd)); self.i=j+2; self.at_boundary=True; continue
                    if ch=='>' and j+1<self.n and self.text[j+1]=='>':
                        self.toks.append(Tok('REDIR','>>',fd)); self.i=j+2; self.at_boundary=True; continue
                    if ch=='<' and j+1<self.n and self.text[j+1]=='<':
                        self.toks.append(Tok('REDIR','<<',fd)); self.i=j+2; self.at_boundary=True; continue
                    self.toks.append(Tok('REDIR',ch,fd)); self.i=j+1; self.at_boundary=True; continue
            # operators / redirects
            if self.starts('&&'):
                self.toks.append(Tok('OP','&&')); self.i+=2; self.at_boundary=True; continue
            if self.starts('||'):
                self.toks.append(Tok('OP','||')); self.i+=2; self.at_boundary=True; continue
            if self.starts(';;'):
                self.toks.append(Tok('OP',';;')); self.i+=2; self.at_boundary=True; continue
            if self.starts('>>'):
                self.toks.append(Tok('REDIR','>>',None)); self.i+=2; self.at_boundary=True; continue
            if self.starts('<<'):
                self.toks.append(Tok('REDIR','<<',None)); self.i+=2; self.at_boundary=True; continue
            if self.starts('>&'):
                self.toks.append(Tok('REDIR','>&',None)); self.i+=2; self.at_boundary=True; continue
            if c in '<>':
                self.toks.append(Tok('REDIR',c,None)); self.i+=1; self.at_boundary=True; continue
            if c in ';|&(){}':
                self.toks.append(Tok('OP',c)); self.i+=1; self.at_boundary=True; continue
            # otherwise a word
            self.toks.append(Tok('WORD', self.read_word()))
            self.at_boundary=False
        self.toks.append(Tok('EOF',None))
        return self.toks

    def read_word(self):
        spans=[]; raw=[]; quoted=False
        while self.i < self.n:
            c=self.peek()
            if c in ' \t\r\n': break
            if c=='#' and not raw:
                break
            if c=='#' and self.at_boundary:
                break
            # operators terminate a word, except proc subst handled below
            if self.starts('<(') or self.starts('>('):
                direction = self.peek()
                script, ni = self.read_balanced(self.i+2, '(', ')')
                spans.append(Span('proc_in' if direction=='<' else 'proc_out', script, False))
                raw.append(direction+'('+script+')'); self.i=ni; continue
            if c in ';|&(){}<>':
                break
            if c=='\\':
                self.i+=1
                if self.i<self.n:
                    nc=self.peek(); self.i+=1
                    spans.append(Span('lit', ' ' if nc=='\n' else nc, False)); raw.append(nc)
                else:
                    spans.append(Span('lit','\\',False)); raw.append('\\')
                continue
            if c=="'":
                quoted=True; self.i+=1; start=self.i
                while self.i<self.n and self.peek()!="'": self.i+=1
                txt=self.text[start:self.i]
                if self.i<self.n and self.peek()=="'": self.i+=1
                spans.append(Span('lit',txt,True)); raw.append(txt); continue
            if c=='"':
                quoted=True; self.i+=1
                inner=[]; iraw=[]
                while self.i<self.n and self.peek()!='"':
                    if self.peek()=='\\':
                        self.i+=1
                        if self.i<self.n:
                            nc=self.peek(); self.i+=1
                            inner.append(Span('lit', nc, True)); iraw.append(nc)
                        continue
                    if self.peek()=='$':
                        sp, r = self.read_dollar(quoted=True)
                        inner.append(sp); iraw.append(r); continue
                    if self.peek()=='`':
                        sp, r = self.read_backtick(quoted=True)
                        inner.append(sp); iraw.append(r); continue
                    start=self.i
                    while self.i<self.n and self.peek() not in '"\\$`': self.i+=1
                    txt=self.text[start:self.i]
                    inner.append(Span('lit',txt,True)); iraw.append(txt)
                if self.i<self.n and self.peek()=='"': self.i+=1
                spans.append(Span('dq', inner, True)); raw.append(''.join(iraw)); continue
            if c=='$':
                sp, r = self.read_dollar(quoted=False)
                spans.append(sp); raw.append(r); continue
            if c=='`':
                sp, r = self.read_backtick(quoted=False)
                spans.append(sp); raw.append(r); continue
            # literal run
            start=self.i
            while self.i<self.n:
                if self.starts('<(') or self.starts('>('): break
                cc=self.peek()
                if cc in ' \t\r\n\\\'"$`#;|&(){}<>':
                    # a # in the middle is literal; don't stop for it here unless boundary (not the case)
                    if cc=='#':
                        self.i+=1; continue
                    break
                self.i+=1
            if self.i==start and self.peek()=='#':
                self.i+=1; txt='#'
            else:
                txt=self.text[start:self.i]
            if txt:
                spans.append(Span('lit',txt,False)); raw.append(txt)
        return Word(spans, ''.join(raw), quoted)

    def read_dollar(self, quoted=False):
        assert self.peek()=='$'
        start=self.i; self.i+=1
        c=self.peek()
        if c=='(':
            if self.i+1<self.n and self.text[self.i+1]=='(':
                # arithmetic: find matching ))
                j=self.i+2; depth=1
                while j<self.n-1:
                    if self.text[j]=='(':
                        depth+=1; j+=1; continue
                    if self.text[j]==')':
                        if j+1<self.n and self.text[j+1]==')' and depth==1:
                            expr=self.text[self.i+2:j]
                            self.i=j+2
                            return Span('arith',expr,quoted), self.text[start:self.i]
                        depth=max(1, depth-1)
                    j+=1
                # fall back to command substitution-ish
            script, ni = self.read_balanced(self.i+1, '(', ')')
            self.i=ni
            return Span('cmd',script,quoted), self.text[start:self.i]
        if c=='{':
            j=self.i+1; depth=1
            while j<self.n:
                if self.text[j]=='{': depth+=1
                elif self.text[j]=='}':
                    depth-=1
                    if depth==0: break
                j+=1
            if j>=self.n:
                self.i=self.n
                return Span('badparam', self.text[start:], quoted), self.text[start:]
            body=self.text[self.i+1:j]
            self.i=j+1
            return Span('param', body, quoted), self.text[start:self.i]
        if c in ['?','$','#','@','*','!','_','-'] or c.isdigit():
            self.i+=1
            return Span('var', c, quoted), self.text[start:self.i]
        if c.isalpha() or c=='_':
            j=self.i
            while j<self.n and (self.text[j].isalnum() or self.text[j]=='_'): j+=1
            name=self.text[self.i:j]; self.i=j
            return Span('var', name, quoted), self.text[start:self.i]
        # invalid bare $, keep as bad variable so parser errors later
        return Span('badvar','',quoted), '$'

    def read_backtick(self, quoted=False):
        start=self.i; self.i+=1; j=self.i; out=[]; esc=False
        while j<self.n:
            ch=self.text[j]
            if esc:
                out.append(ch); esc=False; j+=1; continue
            if ch=='\\':
                esc=True; j+=1; continue
            if ch=='`': break
            out.append(ch); j+=1
        self.i = j+1 if j<self.n else j
        return Span('cmd',''.join(out),quoted), self.text[start:self.i]

    def read_balanced(self, pos, opench, closech):
        # pos is just after the opening delimiter
        depth=1; i=pos; out=[]; quote=None; esc=False
        while i<self.n:
            ch=self.text[i]
            if quote:
                out.append(ch)
                if quote=='"':
                    if esc: esc=False
                    elif ch=='\\': esc=True
                    elif ch=='"': quote=None
                elif quote=="'":
                    if ch=="'": quote=None
                elif quote=='`':
                    if esc: esc=False
                    elif ch=='\\': esc=True
                    elif ch=='`': quote=None
                i+=1; continue
            if ch in ['"',"'",'`']:
                quote=ch; out.append(ch); i+=1; continue
            if ch==opench:
                depth+=1; out.append(ch); i+=1; continue
            if ch==closech:
                depth-=1
                if depth==0:
                    return ''.join(out), i+1
                out.append(ch); i+=1; continue
            out.append(ch); i+=1
        return ''.join(out), i

# ---------------------- parser ----------------------

class Parser:
    def __init__(self, tokens, heredocs=None):
        self.toks=tokens; self.i=0; self.heredocs=list(heredocs or [])

    def cur(self): return self.toks[self.i]
    def peek(self,k=1):
        j=self.i+k
        return self.toks[j] if j<len(self.toks) else Tok('EOF')
    def eat(self):
        t=self.cur(); self.i+=1; return t
    def match_op(self, op):
        if self.cur().typ=='OP' and self.cur().val==op:
            self.i+=1; return True
        return False
    def match_word(self, w):
        if self.cur().typ=='WORD' and self.cur().val.literal_unquoted() and self.cur().val.lit_text()==w:
            self.i+=1; return True
        return False
    def at_stop(self, stop_words, stop_ops):
        t=self.cur()
        if t.typ=='EOF': return True
        if t.typ=='OP' and t.val in stop_ops: return True
        if t.typ=='WORD' and t.val.literal_unquoted() and t.val.lit_text() in stop_words: return True
        return False
    def skip_seps(self):
        while self.cur().typ=='OP' and self.cur().val in [';','\n']:
            self.i+=1

    def parse(self):
        node=self.parse_list(set(), set(['EOF']))
        return node

    def parse_list(self, stop_words, stop_ops):
        items=[]
        self.skip_seps()
        while not self.at_stop(stop_words, stop_ops):
            if self.cur().typ=='OP' and self.cur().val in [')','}']:
                break
            node=self.parse_andor(stop_words, stop_ops)
            items.append((None,node))
            # consume one or more separators; & acts like separator
            if self.cur().typ=='OP' and self.cur().val in [';','\n','&']:
                self.i+=1
                self.skip_seps()
                continue
            if self.at_stop(stop_words, stop_ops): break
            # tolerate adjacency only for recognized stops; otherwise parse error
            # But constructs like "then" are handled by stop_words.
        return ('list', items)

    def parse_andor(self, stop_words, stop_ops):
        parts=[(None, self.parse_pipeline(stop_words, stop_ops))]
        while self.cur().typ=='OP' and self.cur().val in ['&&','||']:
            op=self.eat().val
            parts.append((op, self.parse_pipeline(stop_words, stop_ops)))
        return ('andor', parts) if len(parts)>1 else parts[0][1]

    def parse_pipeline(self, stop_words, stop_ops):
        cmds=[self.parse_command(stop_words, stop_ops)]
        while self.match_op('|'):
            cmds.append(self.parse_command(stop_words, stop_ops))
        return ('pipe',cmds) if len(cmds)>1 else cmds[0]

    def parse_command(self, stop_words, stop_ops):
        t=self.cur()
        if t.typ=='WORD' and t.val.literal_unquoted():
            lw=t.val.lit_text()
            if lw=='if': return self.parse_if()
            if lw=='for': return self.parse_for()
            if lw=='while': return self.parse_while()
            if lw=='case': return self.parse_case()
            # function definition name ( ) { ... }
            if is_name(lw) and self.peek().typ=='OP' and self.peek().val=='(' and self.peek(2).typ=='OP' and self.peek(2).val==')' and self.peek(3).typ=='OP' and self.peek(3).val=='{':
                name=lw; self.i+=4
                body=self.parse_list(set(), set(['}']))
                if not self.match_op('}'):
                    raise ParseError()
                return ('funcdef', name, body)
        if self.match_op('('):
            body=self.parse_list(set(), set([')']))
            if not self.match_op(')'): raise ParseError()
            return ('subshell', body)
        if self.match_op('{'):
            body=self.parse_list(set(), set(['}']))
            if not self.match_op('}'): raise ParseError()
            return ('group', body)
        return self.parse_simple(stop_words, stop_ops)

    def parse_simple(self, stop_words, stop_ops):
        elems=[]
        while True:
            if self.at_stop(stop_words, stop_ops): break
            t=self.cur()
            if t.typ=='OP' and t.val in [';','\n','&','&&','||','|',')','}']:
                break
            if t.typ=='WORD' and t.val.literal_unquoted() and t.val.lit_text() in stop_words:
                break
            if t.typ=='REDIR':
                red=self.eat(); target=None; content=None
                if self.cur().typ!='WORD':
                    raise ParseError()
                target=self.eat().val
                if red.val=='<<':
                    if not self.heredocs:
                        raise ParseError()
                    content=self.heredocs.pop(0)
                elems.append(('redir', red.val, red.fd, target, content))
                continue
            if t.typ=='WORD':
                elems.append(('word', self.eat().val)); continue
            break
        if not elems:
            return ('simple', [])
        return ('simple', elems)

    def parse_if(self):
        self.match_word('if')
        cond=self.parse_list(set(['then']), set())
        if not self.match_word('then'): raise ParseError()
        then_body=self.parse_list(set(['elif','else','fi']), set())
        elifs=[]; else_body=None
        while self.cur().typ=='WORD' and self.cur().val.literal_unquoted() and self.cur().val.lit_text()=='elif':
            self.eat()
            ec=self.parse_list(set(['then']), set())
            if not self.match_word('then'): raise ParseError()
            eb=self.parse_list(set(['elif','else','fi']), set())
            elifs.append((ec,eb))
        if self.match_word('else'):
            else_body=self.parse_list(set(['fi']), set())
        if not self.match_word('fi'): raise ParseError()
        return ('if', cond, then_body, elifs, else_body)

    def parse_for(self):
        self.match_word('for')
        if self.cur().typ!='WORD': raise ParseError()
        namew=self.eat().val
        name=namew.lit_text() or namew.raw
        words=[]
        self.skip_seps()
        if self.match_word('in'):
            while not (self.cur().typ=='WORD' and self.cur().val.literal_unquoted() and self.cur().val.lit_text()=='do'):
                if self.cur().typ=='OP' and self.cur().val in [';','\n']:
                    self.i+=1
                    if self.cur().typ=='WORD' and self.cur().val.literal_unquoted() and self.cur().val.lit_text()=='do': break
                    continue
                if self.cur().typ=='WORD': words.append(self.eat().val); continue
                if self.cur().typ=='EOF': raise ParseError()
                break
        self.skip_seps()
        if not self.match_word('do'): raise ParseError()
        body=self.parse_list(set(['done']), set())
        if not self.match_word('done'): raise ParseError()
        return ('for', name, words, body)

    def parse_while(self):
        self.match_word('while')
        cond=self.parse_list(set(['do']), set())
        if not self.match_word('do'): raise ParseError()
        body=self.parse_list(set(['done']), set())
        if not self.match_word('done'): raise ParseError()
        return ('while', cond, body)

    def parse_case(self):
        self.match_word('case')
        if self.cur().typ!='WORD': raise ParseError()
        word=self.eat().val
        self.skip_seps()
        if not self.match_word('in'): raise ParseError()
        arms=[]
        while True:
            self.skip_seps()
            if self.cur().typ=='WORD' and self.cur().val.literal_unquoted() and self.cur().val.lit_text()=='esac':
                self.eat(); break
            patterns=[]
            if self.cur().typ!='WORD': raise ParseError()
            patterns.append(self.eat().val)
            while self.match_op('|'):
                if self.cur().typ!='WORD': raise ParseError()
                patterns.append(self.eat().val)
            if not self.match_op(')'): raise ParseError()
            body=self.parse_list(set(['esac']), set([';;']))
            arms.append((patterns,body))
            if self.match_op(';;'):
                continue
            if self.cur().typ=='WORD' and self.cur().val.literal_unquoted() and self.cur().val.lit_text()=='esac':
                self.eat(); break
        return ('case', word, arms)

# ---------------------- shell/evaluator ----------------------

class Shell:
    def __init__(self, env=None, stdout_fd=1, stderr_fd=2):
        self.original_env=dict(env if env is not None else os.environ)
        self.vars=dict(self.original_env)
        self.exported=set()
        self.aliases={}
        self.functions={}
        self.last_status=0
        self.errexit=False; self.nounset=False; self.noexec=False
        self.positional=[]; self.arg0=''
        self.local_stack=[]
        self.loop_depth=0; self.function_depth=0
        self.dir_stack=[]; self.cd_old=None
        self.original_home=self.original_env.get('HOME','') or os.path.expanduser('~')
        self.search_path=self.original_env.get('PATH', os.defpath)
        self.proc_subs=[]
        self.stdout_fd=stdout_fd; self.stderr_fd=stderr_fd

    def clone(self):
        s=Shell(self.original_env.copy(), self.stdout_fd, self.stderr_fd)
        s.vars=self.vars.copy(); s.exported=self.exported.copy(); s.aliases=self.aliases.copy(); s.functions=self.functions.copy()
        s.last_status=self.last_status; s.errexit=self.errexit; s.nounset=self.nounset; s.noexec=self.noexec
        s.positional=list(self.positional); s.arg0=self.arg0; s.dir_stack=list(self.dir_stack); s.cd_old=self.cd_old
        s.original_home=self.original_home; s.search_path=self.search_path
        return s

    def write(self, s, fd=1):
        if not isinstance(s, bytes): s=s.encode('utf-8', 'replace')
        try: os.write(fd, s)
        except BrokenPipeError: pass

    def err(self, s): self.write(s, 2)
    def out(self, s): self.write(s, 1)

    def parse(self, script):
        text,hdocs=preprocess_heredocs(script)
        toks=Tokenizer(text).tokenize()
        return Parser(toks,hdocs).parse()

    def run_script(self, script, arg0=None):
        if arg0 is not None: self.arg0=arg0
        try:
            ast=self.parse(script)
        except ParseError as e:
            self.err("nsh: parse error\n")
            self.last_status=255
            return 255
        try:
            status=self.exec_node(ast)
            self.last_status=status
            return status
        except ShellExit as e:
            raise
        except BreakSignal:
            self.panic_unexpected('Break')
            raise ShellExit(101)
        except ContinueSignal:
            self.panic_unexpected('Continue')
            raise ShellExit(101)
        except ReturnSignal:
            self.panic_unexpected('Return')
            raise ShellExit(101)

    def panic_unexpected(self, what):
        self.err(f"nsh: panicked at src/main.rs:133:14:\nunexpected {what}\n")
        self.err("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues\n")

    # Expansion ------------------------------------------------------
    def get_var(self, name, default_unset=False):
        if name=='?': return str(self.last_status)
        if name=='$': return str(os.getpid())
        if name=='#': return str(len(self.positional))
        if name=='!': return '0'
        if name=='-': return ''
        if name=='_': return self.original_env.get('_','')
        if name=='0': return self.arg0
        if name.isdigit():
            idx=int(name)
            return self.positional[idx-1] if 1<=idx<=len(self.positional) else ''
        if name in ('@','*'):
            return ' '.join(self.positional)
        if name in self.vars:
            return self.vars.get(name,'')
        if self.nounset and not default_unset:
            self.err(f"nsh: undefined variable `{name}'\n")
            raise ShellExit(1)
        return ''

    def split_fields(self, val):
        ifs=self.vars.get('IFS',' \t\n')
        if ifs=='': return [val]
        # split at any IFS character, preserving empty fields
        fields=[]; cur=[]
        for ch in val:
            if ch in ifs:
                fields.append(''.join(cur)); cur=[]
            else:
                cur.append(ch)
        fields.append(''.join(cur))
        return fields

    def eval_param(self, body):
        if body.startswith('#'):
            return str(len(self.get_var(body[1:])))
        # substitution ${X/pat/repl} and ${X//pat/repl}
        m=re.match(r'^([A-Za-z_][A-Za-z0-9_]*|[0-9@*?#$_!-])(//?)(.*)$', body, re.S)
        if m and m.group(2).startswith('/'):
            name=m.group(1); rest=m.group(3); val=self.get_var(name)
            if '/' in rest:
                pat,repl=rest.split('/',1)
            else:
                pat,repl=rest,''
            if pat=='':
                return '' if m.group(2)=='//' else val[1:]
            return val.replace(pat,repl) if m.group(2)=='//' else val.replace(pat,repl,1)
        for op in (':-','-',':=','='):
            if op in body:
                name,word=body.split(op,1)
                if not is_name(name) and not name.isdigit():
                    break
                if name in self.vars or (name.isdigit() and self.get_var(name)!=''):
                    return self.get_var(name)
                # default word: expand in assignment-like context
                val=''.join(self.expand_word_to_fields(Word([Span('lit',word,False)]), assignment=True))
                if op in (':=','=') and is_name(name):
                    self.vars[name]=val
                return val
        return self.get_var(body)

    def eval_arith(self, expr):
        # expand $VAR inside expr first
        def repl_dollar(m):
            return self.get_var(m.group(1)) or '0'
        e=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*|[0-9?])', repl_dollar, expr)
        def repl_name(m):
            name=m.group(0)
            if name in ['and','or','not']: return name
            v=self.vars.get(name,'0')
            return v if re.match(r'^-?\d+$', v or '') else '0'
        e=re.sub(r'\b[A-Za-z_][A-Za-z0-9_]*\b', repl_name, e)
        e=e.replace('/', '//')
        try:
            return str(int(eval(e, {"__builtins__":None}, {})))
        except ZeroDivisionError:
            self.err("nsh: panicked at src/eval.rs:38:47:\nattempt to divide by zero\n")
            self.err("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues\n")
            raise ShellExit(101)
        except Exception:
            return ''

    def command_subst(self, script):
        child=self.clone()
        r,w=os.pipe()
        saved_out=os.dup(1); saved_err=os.dup(2)
        # run in a fork to isolate fd changes and state; capture stdout, let stderr pass through
        pid=os.fork()
        if pid==0:
            try:
                os.close(r); os.dup2(w,1); os.close(w)
                try:
                    st=child.run_script(script)
                except ShellExit as e:
                    st=e.code
                os._exit(st & 0xff)
            except BaseException:
                os._exit(1)
        os.close(w)
        chunks=[]
        while True:
            data=os.read(r,4096)
            if not data: break
            chunks.append(data)
        os.close(r)
        try: os.waitpid(pid,0)
        except ChildProcessError: pass
        out=b''.join(chunks).decode('utf-8','replace')
        return out.rstrip('\n')

    def alloc_proc_sub(self, script):
        # Allocate /dev/fd/4, /dev/fd/5, ...
        r,w=os.pipe()
        target=4
        used=[fd for fd,_,_ in self.proc_subs]
        while target in used:
            target+=1
        if r != target:
            try:
                os.dup2(r,target); os.close(r); r=target
            except OSError:
                pass
        pid=os.fork()
        if pid==0:
            try:
                os.close(r); os.dup2(w,1); os.close(w)
                child=self.clone()
                try: st=child.run_script(script)
                except ShellExit as e: st=e.code
                os._exit(st & 0xff)
            except BaseException:
                os._exit(1)
        os.close(w)
        self.proc_subs.append((r,pid,script))
        return f"/dev/fd/{r}"

    def cleanup_proc_subs(self):
        for fd,pid,script in self.proc_subs:
            try: os.close(fd)
            except OSError: pass
            try: os.waitpid(pid,0)
            except ChildProcessError: pass
        self.proc_subs=[]

    def expand_span_value(self, sp, quoted_context=False):
        typ=sp.typ
        if typ=='lit': return sp.val
        if typ=='dq':
            return ''.join(self.expand_span_value(x, True) for x in sp.val)
        if typ=='var': return self.get_var(sp.val)
        if typ=='param': return self.eval_param(sp.val)
        if typ=='arith': return self.eval_arith(sp.val)
        if typ=='cmd': return self.command_subst(sp.val)
        if typ=='proc_in': return self.alloc_proc_sub(sp.val)
        if typ=='proc_out':
            self.err("nsh: panicked at src/expand.rs:238:25:\nnot implemented\n")
            self.err("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues\n")
            raise ShellExit(101)
        if typ in ('badvar','badparam'):
            raise ParseError()
        return ''

    def expand_word_to_fields(self, word, assignment=False):
        # Tilde expansion is based on original HOME and only for unquoted leading literal ~.
        spans=list(word.spans)
        if spans and spans[0].typ=='lit' and not spans[0].quoted and spans[0].val.startswith('~'):
            txt=spans[0].val
            if txt=='~' or txt.startswith('~/'):
                spans[0]=Span('lit', self.original_home + txt[1:], False)
            elif txt.startswith('~'):
                self.err("nsh: warning: ~user is not yet supported\n")
                # replace ~user prefix with HOME
                rest=''
                if '/' in txt:
                    rest='/' + txt.split('/',1)[1]
                spans[0]=Span('lit', self.original_home + rest, False)
        if assignment:
            return [''.join(self.expand_assignment_parts(spans))]
        fields=[]; cur=''; any_part=False
        def flush_cur():
            nonlocal cur, any_part
            if cur!='' or any_part:
                fields.append(cur); cur=''; any_part=False
        for sp in spans:
            if sp.typ in ('var','param','cmd') and not sp.quoted:
                flush_cur()
                val=self.expand_span_value(sp, False)
                vals=self.split_fields(val)
                fields.extend(vals if vals else [''])
            elif sp.typ=='dq':
                cur += self.expand_span_value(sp, True); any_part=True
            else:
                cur += self.expand_span_value(sp, sp.quoted); any_part=True
        flush_cur()
        if not fields:
            fields=['']
        # glob only for simple literal-ish unquoted words containing * or ?
        if self.word_glob_eligible(word):
            expanded=[]
            for f in fields:
                if '*' in f or '?' in f:
                    matches=self.glob_matches(f)
                    if not matches:
                        self.err("nsh: error: no matches\n")
                        raise RuntimeError('glob-no-match')
                    expanded.extend(matches)
                else:
                    expanded.append(f)
            fields=expanded
        return fields

    def expand_assignment_parts(self, spans):
        parts=[]
        for sp in spans:
            if sp.typ=='dq':
                parts.append(''.join(self.expand_span_value(x, True) for x in sp.val))
            elif sp.typ in ('var','param','cmd') and not sp.quoted:
                # field splitting then concatenate without separators
                parts.extend(self.split_fields(self.expand_span_value(sp, False)))
            else:
                parts.append(self.expand_span_value(sp, sp.quoted))
        return parts

    def word_glob_eligible(self, word):
        if word.quoted: return False
        # no globbing after variable/command/arith/proc expansions
        for s in word.spans:
            if s.typ!='lit' or s.quoted:
                return False
        txt=''.join(s.val for s in word.spans)
        return ('*' in txt or '?' in txt)

    def glob_matches(self, pat):
        # Triggered only by * or ?. Bracket expressions are honored by fnmatch.
        if '/' in pat:
            d,b=os.path.split(pat)
            d = d or '.'
            try: names=os.listdir(d)
            except OSError: return []
            entries=[]
            if b.startswith('.'):
                entries.extend(['..','.'])
            for n in names:
                # include hidden for all globs, except . and .. handled above
                entries.append(n)
            matches=[]
            for n in entries:
                if fnmatch.fnmatchcase(n,b):
                    if n in ['.','..'] and b.startswith('.'):
                        matches.append(os.path.join(d,n))
                    else:
                        matches.append(os.path.join(d,n))
            def key(x): return x
            if b.startswith('.'):
                dots=[x for x in matches if os.path.basename(x) in ['..','.']]
                rest=sorted([x for x in matches if os.path.basename(x) not in ['..','.']])
                # original prefers .. before .
                dots=sorted(dots, reverse=True)
                return dots+rest
            return sorted(matches)
        else:
            try: names=os.listdir('.')
            except OSError: return []
            entries=list(names)
            if pat.startswith('.'):
                matches=[]
                if fnmatch.fnmatchcase('..',pat): matches.append('./..')
                if fnmatch.fnmatchcase('.',pat): matches.append('./.')
                rest=sorted([n for n in names if fnmatch.fnmatchcase(n,pat)])
                return matches+rest
            else:
                return sorted([n for n in entries if fnmatch.fnmatchcase(n,pat) and n not in ['.','..']])

    # Assignment helpers ---------------------------------------------
    def assignment_info(self, word):
        # returns (name, value_spans, value_present) if this word syntactically begins NAME=
        spans=word.spans
        prefix=''; idx=None; offset=None
        for si,s in enumerate(spans):
            if s.typ=='lit' and not s.quoted:
                eq=s.val.find('=')
                if eq>=0:
                    prefix += s.val[:eq]
                    if is_name(prefix):
                        rest=s.val[eq+1:]
                        value=[]
                        if rest:
                            value.append(Span('lit',rest,False))
                        value.extend(spans[si+1:])
                        present = bool(rest) or si+1 < len(spans)
                        return prefix, value, present
                    return None
                else:
                    prefix += s.val
            else:
                return None
        return None

    def expand_heredoc(self, content):
        # heredoc bodies are expanded much like double-quoted strings
        try:
            w=Tokenizer(content).read_word() if False else None
            # Simpler: parse as one double-quoted span-like stream
            tok=Tokenizer('"'+content.replace('"','\\"')+'"').tokenize()[0].val
            return ''.join(self.expand_word_to_fields(tok, assignment=True))
        except Exception:
            # fallback variable substitution
            return re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda m:self.get_var(m.group(1)), content)

    # Execution -------------------------------------------------------
    def exec_node(self, node):
        typ=node[0]
        if typ=='list': return self.exec_list(node)
        if typ=='andor': return self.exec_andor(node)
        if typ=='pipe': return self.exec_pipe(node[1])
        if typ=='simple': return self.exec_simple(node[1])
        if typ=='funcdef': self.functions[node[1]]=node[2]; self.last_status=0; return 0
        if typ=='subshell':
            child=self.clone(); st=child.exec_node(node[1]); self.last_status=st; return st
        if typ=='group': return self.exec_node(node[1])
        if typ=='if': return self.exec_if(node)
        if typ=='for': return self.exec_for(node)
        if typ=='while': return self.exec_while(node)
        if typ=='case': return self.exec_case(node)
        return 0

    def maybe_errexit(self, st):
        if self.errexit and st!=0:
            raise ShellExit(st)

    def exec_list(self, node):
        st=0
        for _, child in node[1]:
            if self.noexec:
                self.last_status=0; return 0
            st=self.exec_node(child)
            self.last_status=st
            self.maybe_errexit(st)
        return st

    def exec_andor(self, node):
        st=0; first=True
        for op, child in node[1]:
            if op is None:
                st=self.exec_node(child)
            elif op=='&&':
                if st==0:
                    st=self.exec_node(child)
                # if st nonzero, original keeps it (and with -e would already exit)
            elif op=='||':
                # nsh 0.4.2 executes the rhs regardless of lhs status.
                st=self.exec_node(child)
            self.last_status=st
            self.maybe_errexit(st)
        return st

    def exec_pipe(self, cmds):
        if len(cmds)==1: return self.exec_node(cmds[0])
        prev_read=None; children=[]
        for idx,cmd in enumerate(cmds[:-1]):
            r,w=os.pipe()
            pid=os.fork()
            if pid==0:
                try:
                    if prev_read is not None:
                        os.dup2(prev_read,0)
                    os.dup2(w,1)
                    try: os.close(r); os.close(w)
                    except OSError: pass
                    if prev_read is not None:
                        try: os.close(prev_read)
                        except OSError: pass
                    child=self.clone()
                    try: st=child.exec_node(cmd)
                    except ShellExit as e: st=e.code
                    os._exit(st & 0xff)
                except BaseException:
                    os._exit(1)
            children.append(pid)
            os.close(w)
            if prev_read is not None:
                try: os.close(prev_read)
                except OSError: pass
            prev_read=r
        # Last command in current shell, so read can set variables.
        saved=None
        if prev_read is not None:
            saved=os.dup(0); os.dup2(prev_read,0); os.close(prev_read)
        try:
            st=self.exec_node(cmds[-1])
        finally:
            if saved is not None:
                os.dup2(saved,0); os.close(saved)
        for pid in children:
            try: os.waitpid(pid,0)
            except ChildProcessError: pass
        self.last_status=st
        return st

    def exec_if(self, node):
        _, cond, then_body, elifs, else_body=node
        cst=self.exec_node(cond); self.last_status=cst; self.maybe_errexit(cst)
        if cst==0:
            st=self.exec_node(then_body); self.last_status=st; return st
        for ec,eb in elifs:
            est=self.exec_node(ec); self.last_status=est; self.maybe_errexit(est)
            if est==0:
                st=self.exec_node(eb); self.last_status=st; return st
        if else_body is not None:
            st=self.exec_node(else_body); self.last_status=st; return st
        self.last_status=0; return 0

    def exec_for(self, node):
        _, name, words, body=node
        vals=[]
        for w in words:
            vals.extend(self.expand_word_to_fields(w))
        st=0; self.loop_depth+=1
        try:
            for v in vals:
                self.vars[name]=v
                try:
                    st=self.exec_node(body)
                except ContinueSignal:
                    st=0; continue
                except BreakSignal:
                    st=0; break
        finally:
            self.loop_depth-=1
        self.last_status=st; return st

    def exec_while(self, node):
        _, cond, body=node
        st=0; self.loop_depth+=1
        try:
            while True:
                cst=self.exec_node(cond); self.last_status=cst; self.maybe_errexit(cst)
                if cst!=0: break
                try:
                    st=self.exec_node(body)
                except ContinueSignal:
                    st=0; continue
                except BreakSignal:
                    st=0; break
        finally:
            self.loop_depth-=1
        self.last_status=st; return st

    def exec_case(self, node):
        _, word, arms=node
        vals=self.expand_word_to_fields(word)
        val=vals[0] if vals else ''
        for patterns,body in arms:
            for pword in patterns:
                pat=''.join(self.expand_word_to_fields(pword, assignment=True))
                if fnmatch.fnmatchcase(val, pat):
                    st=self.exec_node(body); self.last_status=st; return st
        self.last_status=0; return 0

    def apply_redirs(self, redirs):
        # returns saved fds list or None on open error; applies in current process
        saved=[]
        def save(fd):
            if fd not in [x[0] for x in saved]:
                try: saved.append((fd, os.dup(fd)))
                except OSError: pass
        for op, fd, target_word, hcontent in redirs:
            fd = 0 if (fd is None and op in ['<','<<']) else (1 if fd is None else fd)
            save(fd)
            try:
                if op=='>':
                    path=self.expand_word_to_fields(target_word)[0]
                    nfd=os.open(path, os.O_WRONLY|os.O_CREAT|os.O_TRUNC, 0o666)
                    os.dup2(nfd, fd); os.close(nfd)
                elif op=='>>':
                    path=self.expand_word_to_fields(target_word)[0]
                    nfd=os.open(path, os.O_WRONLY|os.O_CREAT|os.O_APPEND, 0o666)
                    os.dup2(nfd, fd); os.close(nfd)
                elif op=='<':
                    path=self.expand_word_to_fields(target_word)[0]
                    nfd=os.open(path, os.O_RDONLY)
                    os.dup2(nfd, fd); os.close(nfd)
                elif op=='>&':
                    tgt=self.expand_word_to_fields(target_word)[0]
                    os.dup2(int(tgt), fd)
                elif op=='<<':
                    content=self.expand_heredoc(hcontent or '')
                    r,w=os.pipe(); os.write(w, content.encode()); os.close(w); os.dup2(r, fd); os.close(r)
            except Exception:
                # restore what was saved
                for f,s in reversed(saved):
                    try: os.dup2(s,f); os.close(s)
                    except OSError: pass
                return None
        return saved

    def restore_fds(self, saved):
        if saved:
            for f,s in reversed(saved):
                try: os.dup2(s,f); os.close(s)
                except OSError: pass

    def exec_simple(self, elems):
        if not elems:
            self.last_status=0; return 0
        words=[]; redirs=[]
        for e in elems:
            if e[0]=='word': words.append(e[1])
            else: redirs.append(e[1:])
        # Parse leading assignments, including separated initializer after NAME=
        assignments=[]; idx=0
        while idx < len(words):
            info=self.assignment_info(words[idx])
            if not info: break
            name,vspans,present=info
            if not present:
                if idx+1 >= len(words):
                    self.err("nsh: parse error\n"); self.last_status=255; return 255
                idx += 1
                vspans=words[idx].spans; present=True
            assignments.append((name, Word(vspans)))
            idx += 1
        cmd_words=words[idx:]
        # Alias expansion on command word only, once, before normal expansion of original word.
        if cmd_words:
            lit=cmd_words[0].lit_text() if cmd_words[0].literal_unquoted() else None
            if lit in self.aliases:
                aval=self.aliases[lit]
                alias_words=[]
                for part in aval.split():
                    alias_words.append(Word([Span('lit',part,True)], part, True))
                cmd_words=alias_words + cmd_words[1:]
        # Apply redirections around the command/assignment.
        saved=self.apply_redirs(redirs)
        if saved is None:
            self.last_status=1; return 1
        try:
            # Expand assignments now.
            assign_vals=[]
            for name,w in assignments:
                val=''.join(self.expand_word_to_fields(w, assignment=True))
                assign_vals.append((name,val))
            if not cmd_words:
                for name,val in assign_vals:
                    self.vars[name]=val
                self.last_status=0; return 0
            argv=[]
            try:
                for w in cmd_words:
                    argv.extend(self.expand_word_to_fields(w))
            except RuntimeError as e:
                if str(e)=='glob-no-match':
                    self.last_status=1; return 1
                raise
            if not argv:
                self.last_status=0; return 0
            st=self.run_command(argv, assign_vals)
            self.last_status=st
            return st
        finally:
            self.restore_fds(saved)
            self.cleanup_proc_subs()

    def command_env(self, temp_assigns):
        env=dict(self.original_env)
        for k in self.exported:
            if k in self.vars:
                env[k]=self.vars[k]
            elif k in env:
                env.pop(k,None)
        for k,v in temp_assigns:
            env[k]=v
        return env

    def find_executable(self, cmd):
        if '/' in cmd:
            return cmd if os.path.exists(cmd) else None
        return shutil.which(cmd, path=self.search_path or '')

    def run_command(self, argv, temp_assigns):
        cmd=argv[0]
        # Builtins
        if cmd=='echo': return self.bi_echo(argv[1:])
        if cmd=='alias': return self.bi_alias(argv[1:])
        if cmd=='export': return self.bi_export(argv[1:])
        if cmd=='unset': return self.bi_unset(argv[1:])
        if cmd=='cd': return self.bi_cd(argv[1:])
        if cmd=='source': return self.bi_source(argv[1:])
        if cmd=='exit': return self.bi_exit(argv[1:])
        if cmd=='exec': return self.bi_exec(argv[1:], temp_assigns)
        if cmd=='jobs': return 0
        if cmd=='fg' or cmd=='bg': self.err('nsh: no jobs to run\n'); return 1
        if cmd=='break':
            if self.loop_depth>0: raise BreakSignal()
            raise BreakSignal()
        if cmd=='continue':
            if self.loop_depth>0: raise ContinueSignal()
            raise ContinueSignal()
        if cmd=='return': raise ReturnSignal(0)
        if cmd=='set': return self.bi_set(argv[1:])
        if cmd=='shift': return 0
        if cmd=='eval': return self.run_script(' '.join(argv[1:]))
        if cmd=='read': return self.bi_read(argv[1:])
        if cmd=='wait': return 0
        if cmd=='pushd': return self.bi_pushd(argv[1:])
        if cmd=='popd': return self.bi_popd(argv[1:])
        if cmd=='local': return self.bi_local(argv[1:])
        if cmd in self.functions:
            return self.call_function(cmd, argv[1:])
        return self.run_external(argv, temp_assigns)

    # Builtins --------------------------------------------------------
    def bi_echo(self,args):
        newline=True; interpret=False
        if args and re.match(r'^-[ne]+$', args[0]):
            opt=args[0]
            newline = 'n' not in opt
            interpret = 'e' in opt
            args=args[1:]
        s=' '.join(args)
        if interpret:
            def repl(m):
                seq=m.group(1)
                return {'n':'\n','t':'\t','r':'\r','b':'\b','a':'\a','\\':'\\'}.get(seq,'\\'+seq)
            s=re.sub(r'\\(.)', repl, s)
        if newline: s+='\n'
        self.out(s); return 0

    def bi_alias(self,args):
        if not args:
            for k,v in self.aliases.items(): self.out(f"{k}='{v}'\n")
            return 0
        a=args[0]
        if '=' not in a or not is_name(a.split('=',1)[0]):
            self.err(f"nsh: alias:  --> 1:1\n  |\n1 | {a}\n  | ^---\n  |\n  = expected alias\n")
            return 1
        k,v=a.split('=',1); self.aliases[k]=v; return 0

    def bi_export(self,args):
        for a in args:
            if a in ['-p','--help']:
                continue
            if '=' in a:
                k,v=a.split('=',1)
                if not is_name(k): continue
                self.vars[k]=v; self.exported.add(k)
                if k=='PATH': self.search_path=v
            else:
                if is_name(a): self.exported.add(a)
        return 0

    def bi_unset(self,args):
        for a in args:
            if a.startswith('-'):
                self.err("nsh: unset: error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    unset <NAME>\n\nFor more information try --help\n\n" % a)
                return 1
            self.vars.pop(a,None); self.exported.discard(a)
        return 0

    def bi_cd(self,args):
        if not args:
            dest=self.original_home
        elif args[0]=='-':
            if not self.cd_old: return 1
            dest=self.cd_old
            try: os.chdir(dest); return 0
            except OSError as e:
                self.err(f"nsh: cd: {e.strerror} (os error {e.errno}): `{dest}'\n"); return 1
        else:
            dest=args[0]
        try:
            old=os.getcwd(); os.chdir(dest); self.cd_old=old; return 0
        except OSError as e:
            self.err(f"nsh: cd: {e.strerror} (os error {e.errno}): `{dest}'\n"); return 1

    def bi_source(self,args):
        if not args:
            self.err('nsh: source: filename argument required\n'); return 0
        try:
            with open(args[0], 'r') as f: data=f.read()
        except OSError as e:
            self.err(f'nsh: failed open the file: Os {{ code: {e.errno}, kind: NotFound, message: "{e.strerror}" }}\n')
            return 1
        return self.run_script(data)

    def bi_exit(self,args):
        if not args: raise ShellExit(0)
        try:
            if len(args)>1: code=1
            else: code=int(args[0])
        except Exception:
            code=1
        raise ShellExit(code)

    def bi_exec(self,args,temp_assigns):
        if not args: return 0
        path=self.find_executable(args[0])
        if path is None:
            self.err('nsh: exec: ENOENT: No such file or directory\n')
            return 1
        st=self.run_external(args,temp_assigns, path=path, quiet_direct=True)
        raise ShellExit(st)

    def bi_set(self,args):
        if args and args[0] in ['-h','--help']:
            self.err('nsh: set: set 0.4.2\nSet command.\n\nUSAGE:\n    set [FLAGS]\n\nFLAGS:\n    -e               \n    -h, --help       Prints help information\n    -n               \n    -u               \n    -V, --version    Prints version information\n\n')
            return 1
        if args and args[0] in ['-V','--version']:
            self.out('set 0.4.2'); self.err('nsh: set: \n\n'); return 1
        ok=True
        for a in args:
            if a.startswith('-') and len(a)>1:
                for ch in a[1:]:
                    if ch=='e': self.errexit=True
                    elif ch=='u': self.nounset=True
                    elif ch=='n': self.noexec=True
                    else: ok=False
            else:
                ok=False
        if not ok:
            bad=args[0] if args else ''
            self.err(f"nsh: set: error: Found argument '{bad}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    set [FLAGS]\n\nFor more information try --help\n\n")
            return 1
        return 0

    def bi_read(self,args):
        # Supports read [-p prompt] VAR; one line, no backslash processing.
        prompt=None; rest=[]; i=0
        while i<len(args):
            if args[i]=='-p' and i+1<len(args): prompt=args[i+1]; i+=2
            elif args[i].startswith('-'):
                i+=1
            else:
                rest.append(args[i]); i+=1
        if not rest:
            self.err('read: error: The following required arguments were not provided:\n    <VAR>\n\nUSAGE:\n    read [OPTIONS] <VAR>\n\nFor more information try --help\n\n')
            return 1
        if prompt and os.isatty(0): self.out(prompt)
        # read a line from fd 0
        data=[]
        while True:
            try: b=os.read(0,1)
            except OSError: b=b''
            if not b: break
            if b==b'\n': break
            data.append(b)
        line=b''.join(data).decode('utf-8','replace')
        self.vars[rest[0]]=line
        return 0

    def bi_pushd(self,args):
        if len(args)>1:
            self.err("nsh: pushd: error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    pushd [dir]\n\nFor more information try --help\n\n" % args[1])
            return 1
        if args:
            self.dir_stack.append(args[0])
        return 0

    def bi_popd(self,args):
        if not self.dir_stack:
            self.err('nsh: popd: directory stack empty\n'); return 1
        dest=self.dir_stack.pop()
        try: os.chdir(dest); return 0
        except OSError as e:
            self.err(f"nsh: cd: {e.strerror} (os error {e.errno}): `{dest}'\n"); return 1

    def bi_local(self,args):
        if self.function_depth<=0:
            self.err('nsh: local variable can only be used in a function\n'); return 0
        if not args:
            self.err('nsh: parse error\n'); return 255
        scope=self.local_stack[-1]
        for a in args:
            if '=' in a:
                k,v=a.split('=',1)
            else:
                k,v=a,''
            if k not in scope:
                scope[k]=(self.vars.get(k,None), k in self.vars, k in self.exported)
            self.vars[k]=v
        return 0

    def call_function(self,name,args):
        old_pos=self.positional; self.positional=list(args)
        self.function_depth+=1; self.local_stack.append({})
        st=0
        try:
            try:
                st=self.exec_node(self.functions[name])
            except ReturnSignal as r:
                st=0
        finally:
            scope=self.local_stack.pop()
            for k,(old,existed,was_exp) in reversed(list(scope.items())):
                if existed: self.vars[k]=old
                else: self.vars.pop(k,None)
                if was_exp: self.exported.add(k)
                else: self.exported.discard(k)
            self.function_depth-=1; self.positional=old_pos
        self.last_status=st; return st

    def run_external(self, argv, temp_assigns, path=None, quiet_direct=False):
        cmd=argv[0]
        if path is None:
            path=self.find_executable(cmd)
        if path is None:
            if '/' in cmd:
                self.err(f'nsh: Failed to exec "{cmd}" (ENOENT: No such file or directory)\n')
            else:
                self.err(f"nsh: command not found `{cmd}'\n")
            return 1
        env=self.command_env(temp_assigns)
        try:
            p=subprocess.Popen([path]+argv[1:], env=env, close_fds=True, pass_fds=tuple(fd for fd,_,_ in self.proc_subs))
            rc=p.wait()
            if rc<0: return 128-rc
            return rc
        except FileNotFoundError:
            if '/' in cmd:
                self.err(f'nsh: Failed to exec "{cmd}" (ENOENT: No such file or directory)\n')
            else:
                self.err(f"nsh: command not found `{cmd}'\n")
            return 1
        except PermissionError:
            self.err(f'nsh: Failed to exec "{cmd}" (EACCES: Permission denied)\n')
            return 1

# ---------------------- CLI / rc / interactive ----------------------

def parse_cli(argv):
    prog=os.path.basename(argv[0]) or 'executable'
    args=argv[1:]
    flags={'login':False,'norc':False}; command=None; file=None; c_mode=False
    i=0
    def err_found(a, usage_c=False):
        usage = f"    {prog} -c <command>" if usage_c else f"    {prog} [FLAGS] [OPTIONS] [FILE]"
        sys.stderr.write(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n{usage}\n\nFor more information try --help\n")
        sys.exit(1)
    while i<len(args):
        a=args[i]
        if a in ['--help','-h']:
            sys.stdout.write(HELP_TEMPLATE.format(prog=prog)); sys.exit(0)
        if a=='--version':
            sys.stdout.write(VERSION+'\n'); sys.exit(0)
        if a=='--norc': flags['norc']=True; i+=1; continue
        if a in ['--login','-l']: flags['login']=True; i+=1; continue
        if a=='--':
            i+=1
            if i<len(args):
                if file is None: file=args[i]; i+=1
                else: err_found(args[i], c_mode)
            continue
        if a=='-c' or a.startswith('-c=') or (a.startswith('-c') and a!='-c'):
            c_mode=True
            if a=='-c':
                if i+1>=len(args):
                    sys.stderr.write(f"error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {prog} -c <command>\n\nFor more information try --help\n")
                    sys.exit(1)
                command=args[i+1]; i+=2; continue
            elif a.startswith('-c='):
                command=a[3:]; i+=1; continue
            else:
                # -cl means -c l; -lc is handled as -l + -c next
                if a.startswith('-lc') and a=='-lc':
                    flags['login']=True
                    if i+1>=len(args):
                        sys.stderr.write(f"error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {prog} -c <command>\n\nFor more information try --help\n"); sys.exit(1)
                    command=args[i+1]; i+=2; continue
                command=a[2:]; i+=1; continue
        if a.startswith('-') and a!='-':
            # combined -lc was not caught if extra; support exactly
            if a=='-lc':
                flags['login']=True
                if i+1>=len(args):
                    sys.stderr.write(f"error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {prog} -c <command>\n\nFor more information try --help\n"); sys.exit(1)
                command=args[i+1]; c_mode=True; i+=2; continue
            err_found(a, c_mode)
        # positional file
        if file is None:
            file=a; i+=1; continue
        err_found(a, c_mode)
    return prog, flags, command, file, c_mode

def load_rc(shell):
    home=shell.original_env.get('HOME','')
    paths=[]
    if home: paths.append(os.path.join(home,'.nshrc'))
    xdg=shell.original_env.get('XDG_CONFIG_HOME')
    if xdg: paths.append(os.path.join(xdg,'nsh','nshrc'))
    for p in paths:
        if p and os.path.exists(p):
            try:
                with open(p) as f: data=f.read()
                shell.run_script(data)
            except ShellExit as e:
                raise
            except Exception:
                pass

def interactive(shell):
    # A small compatible-enough interactive loop.  The original does elaborate line editing;
    # for tests, a prompt/read/eval loop is sufficient.
    try:
        while True:
            prompt=shell.vars.get('PROMPT', '\\{current_dir} $ ')
            prompt=prompt.replace('\\{current_dir}', os.getcwd()).replace('\\{reset}','\033[0m').replace('\\{bold}','\033[1m')
            for color,code in [('cyan','\033[36m'),('green','\033[32m'),('red','\033[31m'),('blue','\033[34m'),('yellow','\033[33m'),('magenta','\033[35m')]:
                prompt=prompt.replace('\\{'+color+'}', code)
            prompt=prompt.replace('\\{username}', shell.original_env.get('USER','')).replace('\\{hostname}', os.uname().nodename).replace('\\n','\n')
            shell.out(prompt)
            line=sys.stdin.readline()
            if line=='': break
            try:
                shell.run_script(line)
            except ShellExit as e:
                return e.code
    except KeyboardInterrupt:
        return 130
    return 0

def main():
    prog, flags, command, file, c_mode = parse_cli(sys.argv)
    shell=Shell(os.environ)
    try:
        if not flags.get('norc'):
            load_rc(shell)
        if command is not None:
            try:
                st=shell.run_script(command, arg0='')
                sys.exit(st)
            except ShellExit as e:
                sys.exit(e.code)
        if file is not None:
            try:
                with open(file) as f: data=f.read()
            except OSError as e:
                sys.stderr.write(f'nsh: panicked at src/main.rs:114:34:\nfailed to open the file: Os {{ code: {e.errno}, kind: NotFound, message: "{e.strerror}" }}\n')
                sys.stderr.write('nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues\n')
                sys.exit(101)
            shell.arg0=file
            try:
                st=shell.run_script(data, arg0=file); sys.exit(st)
            except ShellExit as e:
                sys.exit(e.code)
        # no command/file
        if not os.isatty(1):
            sys.stderr.write('nsh: warning: stdout is not a tty\n')
            sys.exit(0)
        sys.exit(interactive(shell))
    except ShellExit as e:
        sys.exit(e.code)

if __name__=='__main__':
    main()
