#!/usr/bin/env python3
import os, sys, subprocess, glob as pyglob, fnmatch, re, time, shutil, tempfile, signal
from dataclasses import dataclass

VERSION = "0.4.2"

HELP_TEMPLATE = """nsh 0.4.2
A command-line shell that focuses on performance and productivity.

USAGE:
    {prog} [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
